try {
  const evaluation = JSON.parse($input.item.json.output);
  const weights = {
    accurate_and_grounded: 0.25,
    beginner_friendly_language: 0.20,
    teaches_by_example: 0.15,
    no_unexplained_jargon: 0.15,
    covers_key_points: 0.15,
    coherent_teaching_flow: 0.10
  };

  let reward = 0;
  let failures = [];
  let allPassed = true;

  for (const checkpoint of evaluation.checkpoints) {
    if (checkpoint.passed) {
      reward += weights[checkpoint.name];
    } else {
      allPassed = false;
      failures.push(checkpoint);
    }
  }

  return {
    json: {
      reward: reward,
      allPassed: allPassed,
      failures: failures,
      evaluation: evaluation,
      variant_id: $node["Get RL Prompt"].json.variant_id,
      topic: $node["Webhook Trigger"].json.body.topic,
      original_lesson: $node["AI Generator"].json.output
    }
  };
} catch (e) {
  return { json: { error: e.message, allPassed: false, reward: 0 } };
}
